public sealed class Customer
{
    public CustomerId Id { get; }               // immutable identity
    public string Name { get; private set; }

    public Customer(CustomerId id, string name) => (Id, Name) = (id, name);

    public void Rename(string name) => Name = name;   // state changes, id does not

    // Equals/GetHashCode deliberately not overridden: EF Core compares entities by
    // reference and tracks one instance per key (identity resolution).
}
